/**
 * Mendapatkan URL Logo PTN resmi AmbisPTN.
 * Menyaring URL wikimedia / Cloudflare R2 lama yang kena 403 / 401.
 */
export function getLogoPtn(ptn) {
  if (!ptn) return null;

  if (typeof ptn === 'string') {
    const trimmed = ptn.trim();
    if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
      if (trimmed.includes('wikimedia.org') || trimmed.includes('r2.dev')) {
        // Abaikan URL bermasalah, lakukan resolusi via slug/nama
      } else {
        return trimmed;
      }
    } else {
      ptn = { nama: trimmed, slug: trimmed.toLowerCase() };
    }
  }

  // 1. Cek properti langsung jika ada URL valid dan bukan wikimedia/r2
  const directUrl = ptn.logo_url || ptn.uni_logo || ptn.logo || ptn.logoUrl;
  if (typeof directUrl === 'string' && directUrl.startsWith('http')) {
    if (!directUrl.includes('wikimedia.org') && !directUrl.includes('r2.dev')) {
      return directUrl;
    }
  }

  const slug = String(ptn.slug || ptn.uni_slug || ptn.idPtn || '').trim().toLowerCase();
  const singkatan = String(ptn.singkatan || ptn.short_name || ptn.uni_short || '').trim();
  const nama = String(ptn.nama || ptn.name || ptn.namaPtn || ptn.uni_name || '').trim();

  // 2. Pencocokan langsung pada dictionary resmi AmbisPTN
  if (slug && AMBIS_LOGO_MAP[slug]) return AMBIS_LOGO_MAP[slug];
  if (singkatan) {
    if (AMBIS_LOGO_MAP[singkatan]) return AMBIS_LOGO_MAP[singkatan];
    if (AMBIS_LOGO_MAP[singkatan.toLowerCase()]) return AMBIS_LOGO_MAP[singkatan.toLowerCase()];
    if (AMBIS_LOGO_MAP[singkatan.toUpperCase()]) return AMBIS_LOGO_MAP[singkatan.toUpperCase()];
  }

  // 3. Pencocokan nama fleksibel
  if (nama) {
    const namaLower = nama.toLowerCase();
    for (const [key, url] of Object.entries(AMBIS_LOGO_MAP)) {
      if (key.length >= 4 && namaLower.includes(key)) {
        return url;
      }
    }
  }

  // 4. Fallback konstruksi CDN AmbisPTN
  if (slug) {
    return 'https://ambisptn.com/media/university_logos/' + slug + '.png';
  }
  if (singkatan) {
    return 'https://ambisptn.com/media/university_logos/' + singkatan.toLowerCase() + '.png';
  }

  return null;
}

/**
 * Mengembalikan inisial kampus (2-5 huruf) untuk monogram badge jika logo gambar gagal atau loading.
 */
export function getMonogramPtn(ptn) {
  if (!ptn) return { inisial: 'PTN', bg: '#0d9488', color: '#ffffff' };

  if (typeof ptn === 'string') {
    ptn = { nama: ptn, singkatan: ptn };
  }

  const singkatan = String(ptn.singkatan || ptn.short_name || ptn.uni_short || '').trim();
  if (singkatan && singkatan.length <= 8) {
    return { inisial: singkatan.toUpperCase(), bg: '#0d9488', color: '#ffffff' };
  }

  const nama = String(ptn.nama || ptn.name || ptn.namaPtn || ptn.uni_name || 'Perguruan Tinggi');
  const kata = nama.replace(/Universitas|Institut|Politeknik|Negeri|UIN|IAIN|Sekolah Tinggi|Akademi/gi, '').trim().split(/\s+/);
  const inisial = kata.length >= 2 ? (kata[0][0] + kata[1][0]).toUpperCase() : nama.slice(0, 3).toUpperCase();

  return { inisial: inisial || 'PTN', bg: '#0f766e', color: '#ffffff' };
}
